let tasks = [];
let currentFilter = 'all';

function addTask() {
    const input = document.getElementById('r9-input');
    const taskText = input.value.trim();

    if (taskText === '') {
        return;
    }

    tasks.push({
        text: taskText,
        completed: false
    });
    renderTasks();
    input.value = '';
}

function deleteTask(index) {
    tasks.splice(index, 1);
    renderTasks();
}

function toggleTask(index) {
    tasks[index].completed = !tasks[index].completed;
    renderTasks();
}

function filterTasks(filterType) {
    currentFilter = filterType;

    // Update active button styling
    document.querySelectorAll('.filter-buttons button').forEach(btn => {
        btn.classList.remove('active');
    });
    document.getElementById(`r9-${filterType}`).classList.add('active');

    renderTasks();
}

function renderTasks() {
    const taskList = document.getElementById('r9-list');
    taskList.innerHTML = '';

    let filteredTasks = tasks;
    if (currentFilter === 'active') {
        filteredTasks = tasks.filter(task => !task.completed);
    } else if (currentFilter === 'done') {
        filteredTasks = tasks.filter(task => task.completed);
    }

    filteredTasks.forEach((task, index) => {
        const li = document.createElement('li');
        li.textContent = task.text;
        if (task.completed) {
            li.style.textDecoration = 'line-through';
            li.style.color = '#888';
        }
        const deleteBtn = document.createElement('button');
        deleteBtn.textContent = 'Delete';
        deleteBtn.onclick = () => deleteTask(index);
        li.appendChild(deleteBtn);
        li.addEventListener('click', (e) => {
            if (e.target !== deleteBtn) {
                toggleTask(index);
            }
        });
        taskList.appendChild(li);
    });
}

document.getElementById('r9-input').addEventListener('keypress', function(e) {
